      COMMON /SMA1ET/ ECPT(100)
      COMMON /SMA1DP/ C(72)    ,G(36)    ,H(16)    ,TEMP(12) ,T(9)    ,
     1                CT(18)   ,GCT(18)  ,KIJ(36)  ,HDETER   ,TEMP1   ,
     2                NGPT     ,DIREC    ,KOUNT    ,TVOL
