      H( 3) = ECPT( 9)
      H( 4) = ECPT(10)
      H( 5) = 1.0D0
      H( 6) = ECPT(12)
      H( 7) = ECPT(13)
      H( 8) = ECPT(14)
      H( 9) = 1.0D0
      H(10) = ECPT(16)
      H(11) = ECPT(17)
