      KIJ( 3) = T(3)
      KIJ( 7) = T(4)
      KIJ( 8) = T(5)
      KIJ( 9) = T(6)
      KIJ(13) = T(7)
      KIJ(14) = T(8)
      KIJ(15) = T(9)
