    double x1=0,y1=0,z1=0;
    double x2=1,y2=0,z2=0;
    double x3=0,y3=1,z3=0;
    double x4=0,y4=0,z4=1;

    double E = 200e9;
    double nu = 0.3;
    double GG = E / (2.0*(1.0+nu));

    // Build H matrix (4x4), row-major as in Fortran H(1..16)
    // H(1)=1, H(2)=x1, H(3)=y1, H(4)=z1
    // H(5)=1, H(6)=x2, H(7)=y2, H(8)=z2
    // H(9)=1, H(10)=x3, H(11)=y3, H(12)=z3
    // H(13)=1, H(14)=x4, H(15)=y4, H(16)=z4
    Matrix4d H;
    H << 1, x1, y1, z1,
         1, x2, y2, z2,
         1, x3, y3, z3,
         1, x4, y4, z4;

    // Invert H and get determinant
    double HDETER = H.determinant();
    Matrix4d Hinv = H.inverse();

